import{_ as l,l as o,o as e,c as i,v as t,p as s,x as n,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"动态权衡与调整","description":"","frontmatter":{"title":"动态权衡与调整","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dynamic-tradeoff.md","filePath":"econ/dynamic-tradeoff.md","lastUpdated":1789023840000}'),p={name:"econ/dynamic-tradeoff.md"};function B(h,a,m,A,_,u){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="动态权衡与调整" tabindex="-1">动态权衡与调整 <a class="header-anchor" href="#动态权衡与调整" aria-label="Permalink to &quot;动态权衡与调整&quot;">​</a></h1><div class="epigraph"><p>有发行成本时，企业不会每时每刻对准 $D^\\ast$；杠杆在一条调整带里游走，只有撞到边界才发债或回购。</p><footer>—— Fischer, Heinkel and Zechner, Dynamic Capital Structure Choice, Journal of Finance 1989；Goldstein, Ju and Leland, Journal of Business 2001；Leary and Roberts, Journal of Finance 2005</footer></div><p><a href="/econ/leland-model">上一课</a>的永久债没有发行成本，杠杆随 \\(V\\) 被动变化，不会主动再平衡。本课缺口是动态权衡：固定或比例发行成本使最优政策变成 \\((s,S)\\) 式调整带。不重解平滑粘贴，不把优序的柠檬折价提前写成唯一摩擦。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态权衡预测杠杆应紧贴 \\(D^\\ast\\)。观察上杠杆缓慢、且有大量「不作为」。Fischer–Heinkel–Zechner（1989）把再资本化写成有成本的期权：只有当杠杆偏离带来的税盾与困境损失，超过发行成本，才调整。Goldstein–Ju–Leland（2001）允许按价值比例再平衡，连接 Miles–Ezzell 的 WACC 世界。缺口是：权衡仍然在，但可检验的不是「截面上人人在 \\(D^\\ast\\)」，而是「偏离的持续性与调整频率」。</p><p><span class="marginnote">Leary–Roberts（2005）：调整行为与有成本的动态权衡一致，对「一次择时留下永久残差」提出挑战。本课先钉机制；下一课 Baker–Wurgler 专写择时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态是杠杆或 \\(V\\) 相对债务。每期（或连续）权衡：税盾流失、困境逼近 vs 发行/回购成本。最优是反射边界：上沿减债（或发股），下沿加债。带的宽度随成本上升、随波动上升（更常碰到边界，但也不愿频繁付成本）。这与存货、现金管理的 \\((s,S)\\) 同构，后课现金持有会再见。</p><p>实证语言：部分调整回归 \\(Lev_{t+1}-Lev_t=\\lambda(D^\\ast-Lev_t)\\) 里的 \\(\\lambda\\) 不是结构速度——若真实政策是带内零调整，线性 \\(\\lambda\\) 会估出一个「慢」的平均数。本课只要：慢不等于没有目标。</p>',9)),(e(),s(c,null,{default:n(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DSTAR%5B%22%E7%9B%AE%E6%A0%87%20D*%20%E4%BB%8D%E6%9D%A5%E8%87%AA%E7%A8%8E%E7%9B%BE%E5%AF%B9%E5%9B%B0%E5%A2%83%22%5D%20--%3E%20BAND%5B%22%E8%B0%83%E6%95%B4%E5%B8%A6%22%5D%0A%20%20COST%5B%22%E5%8F%91%E8%A1%8C%20%2F%20%E5%9B%9E%E8%B4%AD%E6%88%90%E6%9C%AC%22%5D%20--%3E%20BAND%0A%20%20LEV%5B%22%E5%B8%A6%E5%86%85%3A%20%E4%B8%8D%E4%BD%9C%E4%B8%BA%22%5D%20--%3E%20WAIT%5B%22%E6%9D%A0%E6%9D%86%E9%9A%8F%E7%9B%88%E5%88%A9%E4%B8%8E%E4%BB%B7%E6%A0%BC%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20HIT%5B%22%E7%A2%B0%E5%88%B0%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20ADJ%5B%22%E5%8F%91%E5%80%BA%E6%88%96%E5%9B%9E%E8%B4%AD%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>盈利冲击：利润高则账面杠杆被动下降，带内可以不回购——看起来像优序的「盈利企业低杠杆」，其实是权衡加成本。识别留给课程最后一课；这里禁止用被动下降否证目标的存在。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是固定成本破坏凸性规划的「每期一阶条件」。无成本时 Leland 的票息可以随时改；有成本时，等待的期权价值为正，类似实物期权：现在调整放弃「也许价格自己回来」的权利。宏观课序的投资调整成本是近亲；公司金融写在负债侧。</p><p>与 APV：带内债务金额路径不规则，资本预算应用 APV 或时变 WACC，而不是一个永远的目标权重——目标是带的中心，不是每时点的实现。</p><h3 id="动态权衡不是优序" tabindex="-1">动态权衡不是优序 <a class="header-anchor" href="#动态权衡不是优序" aria-label="Permalink to &quot;动态权衡不是优序&quot;">​</a></h3><p>优序：没有目标，杠杆是融资缺口的残差。动态权衡：有目标，有带。两者都可以产生盈利–杠杆负相关。后课择时给出第三种：市场高估时发股，杠杆残差可以永久留下。本课只把「慢」从「无目标」里救出来。</p><p><span class="marginnote">Flannery–Rangan（2006）等报告较快的部分调整；估计对 \\(D^\\ast\\) 设定敏感。结构课不拿某一 \\(\\lambda\\) 当真理，只拿带政策当机制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成部分调整回归综述。下一课市场择时：若股票被错误定价，边界政策本身会被「窗口」移动。也不要把发行成本只理解成承销费：柠檬、稀释、契约谈判都是成本，会加宽带。</p><p>后课默认：权衡目标可以与调整带共存；不作为是最优等待，不是理论失败。择时与个人税尚未进入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发行成本把 \\(D^\\ast\\) 变成调整带；带内杠杆随盈亏与市值游走。</li><li>「慢」不等于没有目标；线性 \\(\\lambda\\) 不是结构速度。</li><li>被动的盈利–杠杆负相关不足以否证权衡。</li><li>出处：Fischer, Heinkel and Zechner, <em>JF</em> 1989；Goldstein, Ju and Leland, <em>JB</em> 2001；Leary and Roberts, <em>JF</em> 2005。</li></ul>',12))])}const b=l(p,[["render",B]]);export{D as __pageData,b as default};
